head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.vScrenID = 'ULDSTF51010.xml';
scwin.gLdMktTp = js_market; // 세션의 시장구분
scwin.rtn;
scwin.gType;
scwin.gTypeMsg = "";
scwin.gUsrId = js_id;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_setHeader = function() {
    dts_updateList.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=MYFORM_NM_GRP_INOUT";
    dts_updateList.reset();
};
scwin.fn_myFormNmList = function() {
    // 사용자서식 명칭 리스트
    var url = "/MyFormPage.do?method=listMyFormGrpPopup" + "&USR_ID=" + scwin.gUsrId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_MyFormNmList.DataID = encodeURI(url);
    dts_MyFormNmList.Reset();
};
scwin.fn_cntRowCheck = function(sval) {
    var cCnt = 0;
    for (i = 1; i <= sval.getTotalRow(); i++) {
        if (sval.getCellData(i, "CHK_FLAG") == 1) {
            cCnt++;
        }
    }
    if (cCnt == 0) {
        return false;
    } else {
        return true;
    }
};
scwin.fn_update = function() {
    scwin.fn_setHeader();
    if (!scwin.fn_cntRowCheck(dts_MyFormNmList)) {
        $c.win.alert("변경할 사용자 서식 그룹을 선택하여 주십시요");
    } else {
        var gMsgCnt = 0;
        var gCheckCnt = 0;
        var tmpInt = 1;
        scwin.rtn = confirm("사용자 서식 그룹 명칭을 변경 하시겠습니까?");
        if (scwin.rtn == 1) // [확인] 버튼이 눌려졌을 경우

        {
            for (var i = 1; i <= dts_MyFormNmList.getTotalRow(); i++) {
                if (dts_MyFormNmList.getCellData(i, "CHK_FLAG") == 1) {
                    if (eval($c.stf.getStringSize(dts_MyFormNmList.getCellData(i, "AFTER_MYFORM_NM")) - 20) > 0) {
                        gCheckCnt++;
                    }
                    dts_updateList.insertRow();
                    dts_updateList.setCellData(tmpInt, "AFTER_MYFORM_NM", dts_MyFormNmList.getCellData(i, "AFTER_MYFORM_NM"));
                    dts_updateList.setCellData(tmpInt, "USR_FORM_GRP_SEQ", dts_MyFormNmList.getCellData(i, "USR_FORM_GRP_SEQ"));
                    dts_updateList.setCellData(tmpInt, "USR_ID", scwin.gUsrId);
                    tmpInt++;
                }
            }
            if (gCheckCnt > 0) {
                $c.win.alert("[ 변경후 ] 항목의 값이  [20 ] byte 가 넘는 명칭이 있습니다. \n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
            } else {
                trs_Save.Action = "/MyFormPage.do?method=updateMyFormGrpPopup&savetype=" + scwin.gType + "&inputMessageId=MYFORM_NM_GRP_INOUT" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
                trs_Save.KeyName = "toinb_dataid4";
                trs_Save.KeyValue = "JSP(I:pInput=dts_updateList)";
                trs_Save.Post();
            }
        }
    }
};
scwin.fn_delete = function() {
    scwin.fn_setHeader();
    if (!scwin.fn_cntRowCheck(dts_MyFormNmList)) {
        $c.win.alert("삭제할 사용자 서식 그룹을 선택하여 주십시요");
    } else {
        var gMsgCnt = 0;
        var gCheckCnt = 0;
        var tmpInt = 1;
        scwin.rtn = confirm("사용자 서식 그룹을 삭제 하시겠습니까? \n서식목록도 함께 삭제됩니다.");
        if (scwin.rtn == 1) // [확인] 버튼이 눌려졌을 경우

        {
            for (var i = 1; i <= dts_MyFormNmList.getTotalRow(); i++) {
                if (dts_MyFormNmList.getCellData(i, "CHK_FLAG") == 1) {
                    dts_updateList.insertRow();
                    dts_updateList.setCellData(tmpInt, "AFTER_MYFORM_NM", dts_MyFormNmList.getCellData(i, "AFTER_MYFORM_NM"));
                    dts_updateList.setCellData(tmpInt, "USR_FORM_GRP_SEQ", dts_MyFormNmList.getCellData(i, "USR_FORM_GRP_SEQ"));
                    dts_updateList.setCellData(tmpInt, "USR_ID", scwin.gUsrId);
                    tmpInt++;
                }
            }
            trs_Save.Action = "/MyFormPage.do?method=updateMyFormGrpPopup&savetype=" + scwin.gType + "&inputMessageId=MYFORM_NM_GRP_INOUT" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            trs_Save.KeyName = "toinb_dataid4";
            trs_Save.KeyValue = "JSP(I:pInput=dts_updateList)";
            trs_Save.Post();
        }
    }
};
scwin.trs_Save_OnSuccess = function() {
    $c.win.alert("사용자서식그룹 명칭이 " + scwin.gTypeMsg + " 되었습니다.");

    //사용자 서식 목록 을  다시 불러옴
    scwin.fn_myFormNmList();
    $c.frame.path("../").fn_myFormNmList();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert("사용자서식그룹 명칭이 " + scwin.gTypeMsg + "이(가) 실패하였습니다.");
};
scwin.btn_delete_onclick = function() {
    scwin.gType = "DI";
    scwin.gTypeMsg = "삭제";
    scwin.fn_delete();
};
scwin.btn_update_onclick = function() {
    scwin.gType = "U";
    scwin.gTypeMsg = "변경";
    scwin.fn_update();
};
scwin.gform_onload = function() {
    scwin.fn_myFormNmList();
};
scwin.img_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
